static char*utf8(const wchar_t*w){int n=WideCharToMultiByte(CP_UTF8,0,w,-1,NULL,0,NULL,NULL);char*s=calloc((size_t)n+1,1);if(s)WideCharToMultiByte(CP_UTF8,0,w,-1,s,n,NULL,NULL);return s;}
static char*escape(const wchar_t*w){char*u=utf8(w);if(!u)return NULL;size_t n=strlen(u);char*s=calloc(n*6+1,1);if(!s){free(u);return NULL;}size_t j=0;for(size_t i=0;i<n;i++){unsigned char c=u[i];if(c=='"'||c=='\\'){s[j++]='\\';s[j++]=c;}else if(c<32){sprintf(s+j,"\\u%04x",c);j+=6;}else s[j++]=c;}SecureZeroMemory(u,n);free(u);return s;}
static BOOL encodeHeader(const wchar_t*text,wchar_t*out,size_t cap){char*u=utf8(text);if(!u)return FALSE;size_t j=0;for(size_t i=0;u[i];i++){unsigned char c=u[i];size_t need=((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.')?1:3;if(j+need>=cap){free(u);return FALSE;}if(need==1)out[j++]=c;else{swprintf(out+j,4,L"%%%02X",c);j+=3;}}out[j]=0;free(u);return TRUE;}
static void saveSession(){if(!sessionPath[0])return;char*s=utf8(cookie);if(!s)return;DATA_BLOB in={(DWORD)strlen(s),(BYTE*)s},out={0};if(CryptProtectData(&in,L"Oriva session",ORIVA_ENTROPY,NULL,NULL,CRYPTPROTECT_UI_FORBIDDEN,&out)){HANDLE f=CreateFileW(sessionPath,GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_HIDDEN,NULL);if(f!=INVALID_HANDLE_VALUE){DWORD n;WriteFile(f,out.pbData,out.cbData,&n,NULL);CloseHandle(f);}LocalFree(out.pbData);}SecureZeroMemory(s,strlen(s));free(s);}
static void readSession(){HANDLE f=CreateFileW(sessionPath,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,0,NULL);if(f==INVALID_HANDLE_VALUE)return;DWORD n,size=GetFileSize(f,NULL);if(size<1||size>8192){CloseHandle(f);return;}BYTE*data=malloc(size);DATA_BLOB in={size,data},out={0};if(data&&ReadFile(f,data,size,&n,NULL)&&n==size&&CryptUnprotectData(&in,NULL,ORIVA_ENTROPY,NULL,NULL,CRYPTPROTECT_UI_FORBIDDEN,&out)){MultiByteToWideChar(CP_UTF8,0,(char*)out.pbData,out.cbData,cookie,510);LocalFree(out.pbData);if(!orivaSessionCookie(cookie))SecureZeroMemory(cookie,sizeof(cookie));}if(data){SecureZeroMemory(data,size);free(data);}CloseHandle(f);}
