static char*requestMethod(const wchar_t*method,const wchar_t*path,const char*body,const wchar_t*file,DWORD*code){
 *code=0;if(!orivaAllowedPath(path))return NULL;HINTERNET session=NULL,connection=NULL,req=NULL;HANDLE input=INVALID_HANDLE_VALUE;char*result=NULL;DWORD length=body?(DWORD)strlen(body):0;wchar_t headers[8192];
 session=WinHttpOpen(L"Oriva Desktop/" ORIVA_VERSION_W,ORIVA_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!session)goto cleanup;if(!wcscmp(path,L"/downloads/windows-update.json")||!wcscmp(path,L"/downloads/windows-update-v2.json"))WinHttpSetTimeouts(session,5000,5000,15000,15000);else if(!wcscmp(method,L"PATCH"))WinHttpSetTimeouts(session,8000,8000,20000,20000);else WinHttpSetTimeouts(session,15000,15000,180000,180000);connection=orivaConnect(session);if(!connection)goto cleanup;req=WinHttpOpenRequest(connection,method,path,NULL,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,ORIVA_REQUEST_FLAGS);if(!req)goto cleanup;if(!orivaNoRedirect(req))goto cleanup;
 if(file){input=CreateFileW(file,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(input==INVALID_HANDLE_VALUE)goto cleanup;LARGE_INTEGER size;if(!GetFileSizeEx(input,&size)||size.QuadPart<0||size.QuadPart>MAX_FILE){status(tr(L"Maximum file size is 25 MB"));goto cleanup;}length=(DWORD)size.QuadPart;const wchar_t*name=wcsrchr(file,L'\\');name=name?name+1:file;char*u=utf8(name);if(!u)goto cleanup;wchar_t encoded[2048];size_t j=0;for(size_t i=0;u[i]&&j<2030;i++){unsigned char c=u[i];if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.')encoded[j++]=c;else{swprintf(encoded+j,4,L"%%%02X",c);j+=3;}}encoded[j]=0;free(u);wchar_t encodedTitle[4096];if(!encodeHeader(saveTitle,encodedTitle,4096))goto cleanup;swprintf(headers,8192,L"Origin: %ls\r\nContent-Type: application/octet-stream\r\nX-File-Name: %ls\r\nX-File-Title: %ls\r\nX-File-Type: application/octet-stream\r\n",ORIGIN,encoded,encodedTitle);
 }else swprintf(headers,8192,L"Origin: %ls\r\nContent-Type: application/json\r\n",ORIGIN);
 if(!wcscmp(path,L"/downloads/windows-update.json")||!wcscmp(path,L"/downloads/windows-update-v2.json"))WinHttpAddRequestHeaders(req,L"Cache-Control: no-cache\r\nPragma: no-cache\r\n",(DWORD)-1L,WINHTTP_ADDREQ_FLAG_ADD);
 if(cookie[0]){wchar_t c[600];swprintf(c,600,L"Cookie: %ls",cookie);WinHttpAddRequestHeaders(req,c,(DWORD)-1L,WINHTTP_ADDREQ_FLAG_ADD|WINHTTP_ADDREQ_FLAG_REPLACE);}
 if(!WinHttpSendRequest(req,headers,(DWORD)-1L,file?NULL:(void*)body,file?0:length,length,0))goto cleanup;
 if(file){BYTE buffer[65536];DWORD n,total=0;while(ReadFile(input,buffer,sizeof(buffer),&n,NULL)&&n){DWORD written;if(!WinHttpWriteData(req,buffer,n,&written)||written!=n)goto cleanup;total+=n;wchar_t msg[120];swprintf(msg,120,tr(L"Uploading... %u%%"),length?total*100/length:100);status(msg);}if(total!=length)goto cleanup;}
 if(!WinHttpReceiveResponse(req,NULL)||!orivaResponseIdentity(req))goto cleanup;DWORD n=sizeof(DWORD);WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,code,&n,WINHTTP_NO_HEADER_INDEX);
 if(*code==200&&!wcscmp(path,L"/api/login")){wchar_t value[2048];DWORD size=sizeof(value);if(WinHttpQueryHeaders(req,WINHTTP_QUERY_SET_COOKIE,WINHTTP_HEADER_NAME_BY_INDEX,value,&size,WINHTTP_NO_HEADER_INDEX)){wchar_t*end=wcschr(value,L';');if(end)*end=0;if(orivaSessionCookie(value)){wcsncpy(cookie,value,511);saveSession();}}}
 size_t used=0;result=calloc(1,1);for(;;){BYTE buffer[4096];DWORD count=0;if(!WinHttpReadData(req,buffer,sizeof(buffer),&count)){*code=0;goto cleanup;}if(!count)break;if(used+count>32*1024*1024){*code=0;goto cleanup;}char*next=realloc(result,used+count+1);if(!next){*code=0;goto cleanup;}result=next;memcpy(result+used,buffer,count);used+=count;result[used]=0;}
 cleanup:if(input!=INVALID_HANDLE_VALUE)CloseHandle(input);if(req)WinHttpCloseHandle(req);if(connection)WinHttpCloseHandle(connection);if(session)WinHttpCloseHandle(session);return result;
}
static char*request(const wchar_t*path,const char*body,const wchar_t*file,DWORD*code){return requestMethod(L"POST",path,body,file,code);}
static void error(char*response,DWORD code){wchar_t text[1024];const char*s=response?strstr(response,"\"error\""):NULL;if(s&&(s=strchr(s,':'))&&(s=strchr(s,'"'))){s++;const char*end=strchr(s,'"');if(end)MultiByteToWideChar(CP_UTF8,0,s,(int)(end-s)>1000?1000:(int)(end-s),text,1000);else s=NULL;if(s){int len=MultiByteToWideChar(CP_UTF8,0,s,(int)(end-s)>1000?1000:(int)(end-s),text,1000);text[len]=0;}}if(!s){
 swprintf(text,1024,code?tr(L"Oriva returned an error (%lu). Try again."):tr(L"Could not complete the request. Check your connection and try again."),code);
}if(action==LOGIN){SendMessageW(window,AUTH_ERROR,0,(LPARAM)tr(text));status(L"");}else{status(tr(text));orivaMessageBox(window,text,L"Oriva",MB_OK|MB_ICONINFORMATION);}}
